class Solution:
    def reverseKGroup(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        dummy = ListNode(0, head); group_prev = dummy
        while True:
            kth = group_prev
            for _ in range(k):
                kth = kth.next
                if kth is None: return dummy.next
            group_next = kth.next
            prev, curr = group_next, group_prev.next
            while curr is not group_next:
                nxt = curr.next; curr.next = prev; prev = curr; curr = nxt
            old_head = group_prev.next
            group_prev.next = kth
            group_prev = old_head

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head), groupPrev = dummy;
        while (true) {
            ListNode kth = groupPrev;
            for (int i = 0; i < k; i++) { kth = kth.next; if (kth == null) return dummy.next; }
            ListNode groupNext = kth.next, prev = groupNext, curr = groupPrev.next;
            while (curr != groupNext) { ListNode next = curr.next; curr.next = prev; prev = curr; curr = next; }
            ListNode oldHead = groupPrev.next; groupPrev.next = kth; groupPrev = oldHead;
        }
    }
}

