class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        n, m = len(haystack), len(needle)
        for start in range(n - m + 1):
            if haystack[start:start + m] == needle:
                return start
        return -1

class Solution {
    public int strStr(String haystack, String needle) {
        int n = haystack.length(), m = needle.length();
        for (int start = 0; start <= n - m; start++) {
            int j = 0;
            while (j < m && haystack.charAt(start + j) == needle.charAt(j)) j++;
            if (j == m) return start;
        }
        return -1;
    }
}

class Solution:
    def divide(self, dividend: int, divisor: int) -> int:
        if dividend == -(2**31) and divisor == -1:
            return 2**31 - 1
        negative = (dividend < 0) != (divisor < 0)
        a, b = abs(dividend), abs(divisor)
        quotient = 0
        while a >= b:
            shift = 0
            while a >= (b << (shift + 1)):
                shift += 1
            quotient += 1 << shift
            a -= b << shift
        return -quotient if negative else quotient

class Solution {
    public int divide(int dividend, int divisor) {
        if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;
        boolean negative = (dividend < 0) != (divisor < 0);
        long a = Math.abs((long) dividend), b = Math.abs((long) divisor), quotient = 0;
        while (a >= b) {
            int shift = 0;
            while (a >= (b << (shift + 1))) shift++;
            quotient += 1L << shift;
            a -= b << shift;
        }
        long result = negative ? -quotient : quotient;
        return (int) result;
    }
}

